package com.mamtrex.hospital.auth; import jakarta.validation.constraints.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/auth") public class AuthController { private final UserAccountRepository repo; private final PasswordEncoder encoder; private final JwtService jwt; public AuthController(UserAccountRepository r,PasswordEncoder e,JwtService j){repo=r;encoder=e;jwt=j;} public record LoginRequest(@NotBlank String username,@NotBlank String password){} public record LoginResponse(String accessToken,String tokenType){} @PostMapping("/login") public LoginResponse login(@RequestBody LoginRequest req){var u=repo.findByUsername(req.username()).filter(UserAccount::isEnabled).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));if(!encoder.matches(req.password(),u.getPasswordHash()))throw new IllegalArgumentException("Invalid credentials");return new LoginResponse(jwt.issue(u),"Bearer");} }
